pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 blockNumber, address actor) public {
        blockNumber = bound(blockNumber, 1, type(uint256).max - 1);
        vm.assume(blockNumber % 15 != 0);
        vm.assume(actor != address(0));

        uint256 firstBlock = blockNumber;
        uint256 secondBlock = blockNumber;

        vm.roll(firstBlock);
        vm.warp(firstBlock);
        vm.deal(actor, 20 ether);
        vm.prank(actor);
        (bool ok1, ) = address(c).call{value: 10 ether}("");
        require(ok1, "first call failed");

        uint256 pastBeforeSecond = c.pastBlockTime();

        vm.roll(secondBlock);
        vm.warp(secondBlock);
        vm.prank(actor);
        (bool ok2, ) = address(c).call{value: 10 ether}("");

        assertTrue(!ok2);
    }
}
